<?php ob_start(); ?><h1>Operation reports</h1><form method="get"><input name="q" value="<?= esc($q) ?>" placeholder="S/O, machine, supervisor"><label>Date <input name="date" type="date" value="<?= esc($date ?? '') ?>"></label><label>Machine <select name="machine_id"><option value="">All machines</option><?php foreach($machines as $machine): ?><option value="<?= (int)$machine['id'] ?>" <?= (string)$machineId===(string)$machine['id']?'selected':'' ?>><?= esc($machine['machine_name']) ?></option><?php endforeach ?></select></label><label>Supervisor <select name="supervisor_id"><option value="">All supervisors</option><?php foreach($supervisors as $supervisor): ?><option value="<?= (int)$supervisor['id'] ?>" <?= (string)$supervisorId===(string)$supervisor['id']?'selected':'' ?>><?= esc($supervisor['name']) ?></option><?php endforeach ?></select></label><button>Search</button><a href="<?= site_url('admin/operations') ?>">Clear</a></form>
<section><p><?= (int)$total ?> matching process record(s)</p><table><thead><tr><th>S/O</th><th>Machine</th><th>Sector / activity</th><th>Supervisor</th><th>Status</th><th>Start / end (MYT)</th><th>Passed / rejected</th><th></th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= esc($row['so_number'] ?? '-') ?></td><td><?= esc($row['machine_name']) ?></td><td><?= esc($row['sector_name'].' / '.$row['activity_name']) ?></td><td><?= esc($row['supervisor_name']) ?></td><td><?= esc($row['status']) ?></td><td><?= esc(kinta_local_time($row['started_at'] ?? null, '-')) ?><br><?= esc(kinta_local_time($row['ended_at'] ?? null, '-')) ?></td><td><?= esc($row['qty_passed'] ?? '-') ?> / <?= esc($row['qty_rejected'] ?? '-') ?></td><td><a class="view-record" href="<?= site_url('admin/operations/'.$row['id']) ?>" aria-label="View process record" title="View process record"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="3" fill="none" stroke="currentColor" stroke-width="2"/></svg></a></td></tr><?php endforeach ?></tbody></table>
<?php if ($pageCount > 1): ?><nav aria-label="Report pages"><?php if ($page > 1 && isset($pageUrls[$page-1])): ?><a href="<?= esc($pageUrls[$page-1]) ?>">Previous</a><?php endif ?> <?php foreach ($pageUrls as $number => $url): ?><a href="<?= esc($url) ?>" <?= $number === $page ? 'aria-current="page"' : '' ?>><?= (int)$number ?></a> <?php endforeach ?><?php if ($page < $pageCount && isset($pageUrls[$page+1])): ?><a href="<?= esc($pageUrls[$page+1]) ?>">Next</a><?php endif ?></nav><?php endif ?></section><?php $content=ob_get_clean(); echo view('admin/shell',['title'=>$title,'content'=>$content]); ?>
